import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        // keys[r] = (S[r] - r) mod k; a valid subarray (l, r] has keys[l] == keys[r] and r - l < k.
        long[] keys = new long[n + 1];
        for (int r = 1; r <= n; r++) keys[r] = (keys[r - 1] + nextLong() - 1) % k;
        // Compress keys so the frequency table is a plain array.
        long[] uniq = keys.clone();
        Arrays.sort(uniq);
        int u = 0;
        for (int i = 0; i <= n; i++) if (i == 0 || uniq[i] != uniq[i - 1]) uniq[u++] = uniq[i];
        int[] id = new int[n + 1];
        for (int r = 0; r <= n; r++) id[r] = Arrays.binarySearch(uniq, 0, u, keys[r]);
        long[] freq = new long[u];
        freq[id[0]] = 1;
        long answer = 0;
        for (int r = 1; r <= n; r++) {
            if (r >= k) freq[id[(int) (r - k)]]--; // prefix r-k would give length >= k
            answer += freq[id[r]];
            freq[id[r]]++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), nextInt()
	// keys[r] = (S[r] - r) mod k; a valid subarray (l, r] has keys[l] == keys[r] and r - l < k.
	keys := make([]int64, n+1)
	for r := 1; r <= n; r++ {
		keys[r] = (keys[r-1] + nextInt() - 1) % k
	}
	// Compress keys so the frequency table is a plain array.
	uniq := slices.Clone(keys)
	slices.Sort(uniq)
	uniq = slices.Compact(uniq)
	id := make([]int, n+1)
	for r, key := range keys {
		id[r], _ = slices.BinarySearch(uniq, key)
	}
	freq := make([]int64, len(uniq))
	freq[id[0]] = 1
	var answer int64
	for r := 1; r <= n; r++ {
		if int64(r) >= k {
			freq[id[int64(r)-k]]-- // prefix r-k would give length >= k
		}
		answer += freq[id[r]]
		freq[id[r]]++
	}
	fmt.Println(answer)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
